// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title MockFeeOnTransferToken
 * @notice ERC20 token that charges a fee on every transfer (for testing)
 */
contract MockFeeOnTransferToken is ERC20 {
    uint256 public feeBps; // Fee in basis points (100 = 1%)

    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply,
        uint256 _feeBps
    ) ERC20(name, symbol) {
        require(_feeBps <= 1000, "Fee cannot exceed 10%");
        feeBps = _feeBps;
        _mint(msg.sender, initialSupply);
    }

    function _update(address from, address to, uint256 value) internal virtual override {
        if (from != address(0) && to != address(0)) {
            // Calculate fee (basis points)
            uint256 fee = (value * feeBps) / 10000;
            uint256 amountAfterFee = value - fee;

            // Burn the fee
            super._update(from, address(0), fee);
            // Transfer remaining amount
            super._update(from, to, amountAfterFee);
        } else {
            // Minting or burning - no fee
            super._update(from, to, value);
        }
    }
}

TokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./BondingCurveToken.sol";

contract TokenFactory {
    event TokenCreated(
        address indexed tokenAddress,
        string name,
        string symbol,
        address indexed creator,
        uint256 initialPrice,
        uint256 timestamp
    );

    mapping(address => address[]) public creatorTokens;
    address[] public allTokens;

    function createToken(
        string memory name,
        string memory symbol,
        uint256 initialPrice
    ) external returns (address) {
        require(initialPrice > 0, "Initial price must be > 0");

        BondingCurveToken newToken = new BondingCurveToken(
            name,
            symbol,
            msg.sender,
            initialPrice
        );

        address tokenAddress = address(newToken);

        creatorTokens[msg.sender].push(tokenAddress);
        allTokens.push(tokenAddress);

        emit TokenCreated(tokenAddress, name, symbol, msg.sender, initialPrice, block.timestamp);

        return tokenAddress;
    }

    function getCreatorTokens(address creator) external view returns (address[] memory) {
        return creatorTokens[creator];
    }

    function getAllTokens() external view returns (address[] memory) {
        return allTokens;
    }

    function getTokenCount() external view returns (uint256) {
        return allTokens.length;
    }
}

